/**
 * hypothesis.ts — Manual six-world scratchpad builder.
 *
 * This module is Kiro work (2026-10-31). It has no dependency on DOM, React,
 * Next.js, AI, storage, solver, or private answer data.
 *
 * The inherited application (engine, renderer, generator, components) is Codex work.
 */

import type { Suspect, SuspectId } from "./types";

/** A stable identifier encoding culpritId and fact. Six legal values exist. */
export type HypothesisId = `${SuspectId}-false` | `${SuspectId}-true`;

/** One entry in the six-world Cartesian product used as a player scratchpad. */
export type Hypothesis = {
  /** Stable ID derived from culpritId and fact; suitable as a React key and data-testid suffix. */
  readonly id: HypothesisId;
  readonly culpritId: SuspectId;
  readonly fact: boolean;
  /** Display name from the matching Suspect, for rendering without a separate lookup. */
  readonly suspectDisplayName: string;
};

/**
 * Build the Cartesian product of suspects × {false, true} as an ordered array of six Hypothesis
 * objects. The suspects are emitted in the order given by `displayOrder`; within each suspect,
 * fact=false appears before fact=true.
 *
 * - Does NOT mutate `suspects` or `displayOrder`.
 * - Does NOT call the solver, read private answer data, or access any UI or storage layer.
 * - Returns a new array on every call; callers may mutate the result without affecting inputs.
 *
 * @param suspects     All Suspect objects for the current case (used for displayName lookup).
 * @param displayOrder The SuspectId ordering that controls card layout (matches publicSnapshot order).
 */
export function buildHypotheses(
  suspects: readonly Suspect[],
  displayOrder: readonly SuspectId[],
): Hypothesis[] {
  // Build a lookup map without mutating the input array.
  const nameById = new Map<SuspectId, string>();
  for (const suspect of suspects) {
    nameById.set(suspect.id, suspect.displayName);
  }

  const result: Hypothesis[] = [];
  for (const culpritId of displayOrder) {
    const suspectDisplayName = nameById.get(culpritId) ?? culpritId;
    result.push(
      {
        id: `${culpritId}-false` as HypothesisId,
        culpritId,
        fact: false,
        suspectDisplayName,
      },
      {
        id: `${culpritId}-true` as HypothesisId,
        culpritId,
        fact: true,
        suspectDisplayName,
      },
    );
  }
  return result;
}

'use client';

/**
 * HypothesisBoard.tsx — Player-owned manual deduction scratchpad.
 *
 * Original authorship: Kiro (2026-10-31). Hypothesis board feature (pure client
 * component, local state only, never reads solver/case/culprit identity).
 *
 * Ten-language secondary UI localization: Kiro (2026-10-31). The inline
 * two-locale `t(ko, en)` pattern has been replaced with a lookup into the
 * secondary-ui catalogue covering all ten supported locales. Component behaviour,
 * game invariants, and data flow are unchanged.
 *
 * The inherited application code (Game.tsx, CrossExamination.tsx, CSS, engine)
 * is Codex work. Codex is responsible for rendering this component and styling
 * the hypothesis-board / hypothesis-grid / hypothesis-card class names.
 * Codex integration: optional frozen-content language boundaries for older shares.
 */

import { useState } from 'react';
import { t, fill } from '@/lib/i18n/secondary-ui';
import { getDirection } from '@/lib/i18n/locales';
import { buildHypotheses, type Hypothesis, type HypothesisId } from '@/lib/game/hypothesis';
import type { Locale, Suspect, SuspectId } from '@/lib/game/types';

type Props = {
  suspects: readonly Suspect[];
  locale: Locale;
  contentLocale?: Locale;
  /** factLabels[0] = label for fact=false event; factLabels[1] = label for fact=true event. */
  factLabels: readonly [string, string];
};

/**
 * Manual six-world hypothesis board.
 *
 * Renders six toggleable cards representing every (culpritId × fact) world.
 * The player eliminates worlds they consider impossible; the board never
 * auto-eliminates or reveals which world is correct.
 */
export default function HypothesisBoard({ suspects, locale, contentLocale = locale, factLabels }: Props) {
  // Derive display order from the suspects array (mirrors publicSnapshot ordering).
  const displayOrder: SuspectId[] = suspects.map((s) => s.id as SuspectId);
  const hypotheses: Hypothesis[] = buildHypotheses(suspects, displayOrder);

  // Set of eliminated hypothesis IDs; never mutated — always replaced with a new Set.
  const [eliminated, setEliminated] = useState<Set<HypothesisId>>(new Set());

  function toggle(id: HypothesisId) {
    setEliminated((prev) => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  }

  function reset() {
    setEliminated(new Set());
  }

  const total = hypotheses.length; // always 6
  const remaining = total - eliminated.size;

  // The one remaining card — only meaningful when exactly one is left.
  const lastCard: Hypothesis | undefined =
    remaining === 1 ? hypotheses.find((h) => !eliminated.has(h.id)) : undefined;

  return (
    <section
      className="hypothesis-board"
      data-testid="hypothesis-board"
      aria-label={t(locale, 'hyp-board-aria')}
    >
      <h2>{t(locale, 'hyp-heading')}</h2>

      <p className="hypothesis-instruction">{t(locale, 'hyp-instruction')}</p>

      {/* Remaining count */}
      <p className="hypothesis-count" aria-live="polite">
        {fill(t(locale, 'hyp-count'), { remaining, total })}
        {remaining === 1 && lastCard && (
          <>
            {' — '}
            <strong>{t(locale, 'hyp-last-label')}</strong>
          </>
        )}
      </p>

      {/* Zero-remaining message */}
      {remaining === 0 && (
        <p className="hypothesis-empty" role="status">
          {t(locale, 'hyp-empty')}
        </p>
      )}

      <div className="hypothesis-grid">
        {hypotheses.map((h) => {
          const isEliminated = eliminated.has(h.id);
          const factLabel = h.fact ? factLabels[1] : factLabels[0];
          const statusText = isEliminated
            ? t(locale, 'hyp-status-eliminated')
            : t(locale, 'hyp-status-possible');
          const isLast = lastCard?.id === h.id;

          return (
            <button
              key={h.id}
              className="hypothesis-card"
              data-testid={`hypothesis-card-${h.id}`}
              aria-pressed={isEliminated}
              onClick={() => toggle(h.id)}
              type="button"
            >
              <span className="hypothesis-suspect" lang={contentLocale} dir={getDirection(contentLocale)}>{h.suspectDisplayName}</span>
              <span className="hypothesis-fact" lang={contentLocale} dir={getDirection(contentLocale)}>{factLabel}</span>
              <span className="hypothesis-status">{statusText}</span>
              {isLast && (
                <span className="hypothesis-last-label">
                  {t(locale, 'hyp-last-label')}
                </span>
              )}
            </button>
          );
        })}
      </div>

      <button
        className="hypothesis-reset"
        data-testid="hypothesis-reset"
        onClick={reset}
        type="button"
      >
        {t(locale, 'hyp-reset')}
      </button>
    </section>
  );
}

/**
 * tests/hypothesis.test.ts — Hypothesis builder tests.
 *
 * This test file is Kiro work (2026-10-31).
 * Uses node:test and node:assert/strict, matching the project's existing test style.
 */

import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { SUSPECT_IDS, type SuspectId, type Suspect } from "../src/lib/game/types";
import { buildHypotheses, type HypothesisId } from "../src/lib/game/hypothesis";

// ── Helpers ──────────────────────────────────────────────────────────────────

function permutations<T>(items: T[]): T[][] {
  if (items.length === 0) return [[]];
  return items.flatMap((item, index) =>
    permutations(items.filter((_, i) => i !== index)).map((tail) => [item, ...tail]),
  );
}

/** Minimal Suspect fixture — only fields used by buildHypotheses. */
function makeSuspect(id: SuspectId, displayName: string): Suspect {
  return {
    id,
    displayName,
    kind: "cup",
    face: { x: 0.5, y: 0.5, scale: 0.15, rotation: 0 },
    personalityId: "dry",
  };
}

const SAMPLE_SUSPECTS: readonly Suspect[] = [
  makeSuspect("s0", "머그컵"),
  makeSuspect("s1", "스탠드"),
  makeSuspect("s2", "키보드"),
];

const ALL_ORDERS = permutations([...SUSPECT_IDS]) as SuspectId[][];

// ── Tests ─────────────────────────────────────────────────────────────────────

test("all six permutations of suspect display order produce exactly six hypotheses", () => {
  for (const order of ALL_ORDERS) {
    const hypotheses = buildHypotheses(SAMPLE_SUSPECTS, order);
    assert.equal(hypotheses.length, 6, `order ${order.join(",")} → expected 6 hypotheses`);
  }
});

test("display order is respected: suspects appear in displayOrder sequence", () => {
  for (const order of ALL_ORDERS) {
    const hypotheses = buildHypotheses(SAMPLE_SUSPECTS, order);
    // Cards 0,1 belong to order[0]; cards 2,3 to order[1]; cards 4,5 to order[2].
    for (let i = 0; i < 3; i++) {
      const expected = order[i];
      assert.equal(
        hypotheses[i * 2].culpritId, expected,
        `pair ${i} (even): expected culpritId ${expected}`,
      );
      assert.equal(
        hypotheses[i * 2 + 1].culpritId, expected,
        `pair ${i} (odd): expected culpritId ${expected}`,
      );
    }
  }
});

test("within each suspect pair, fact=false appears before fact=true", () => {
  for (const order of ALL_ORDERS) {
    const hypotheses = buildHypotheses(SAMPLE_SUSPECTS, order);
    for (let i = 0; i < 3; i++) {
      assert.equal(hypotheses[i * 2].fact, false, `pair ${i} first card should have fact=false`);
      assert.equal(hypotheses[i * 2 + 1].fact, true, `pair ${i} second card should have fact=true`);
    }
  }
});

test("all six IDs are unique within a single call", () => {
  for (const order of ALL_ORDERS) {
    const hypotheses = buildHypotheses(SAMPLE_SUSPECTS, order);
    const ids = hypotheses.map((h) => h.id);
    const unique = new Set(ids);
    assert.equal(unique.size, 6, `order ${order.join(",")} produced duplicate IDs: ${ids.join(", ")}`);
  }
});

test("hypothesis IDs are stable: same culpritId+fact always yields the same id, regardless of display order", () => {
  // Collect (culpritId, fact) → id mapping from the first order.
  const first = buildHypotheses(SAMPLE_SUSPECTS, ["s0", "s1", "s2"]);
  const canonical = new Map<string, HypothesisId>();
  for (const h of first) {
    canonical.set(`${h.culpritId}-${h.fact}`, h.id);
  }

  // Every other display order must produce the same id for the same (culpritId, fact).
  for (const order of ALL_ORDERS) {
    const hypotheses = buildHypotheses(SAMPLE_SUSPECTS, order);
    for (const h of hypotheses) {
      const key = `${h.culpritId}-${h.fact}`;
      assert.equal(
        h.id,
        canonical.get(key),
        `ID mismatch for ${key} under order ${order.join(",")}`,
      );
    }
  }
});

test("ID format matches '<suspectId>-<fact>' template literal", () => {
  const hypotheses = buildHypotheses(SAMPLE_SUSPECTS, ["s0", "s1", "s2"]);
  for (const h of hypotheses) {
    const expected = `${h.culpritId}-${h.fact}` as HypothesisId;
    assert.equal(h.id, expected);
  }
});

test("suspectDisplayName is taken from the suspects array, not the display order entry alone", () => {
  const renamed: Suspect[] = [
    makeSuspect("s0", "Alpha"),
    makeSuspect("s1", "Beta"),
    makeSuspect("s2", "Gamma"),
  ];
  const hypotheses = buildHypotheses(renamed, ["s2", "s0", "s1"]);
  // Cards 0,1 → s2 → "Gamma"
  assert.equal(hypotheses[0].suspectDisplayName, "Gamma");
  assert.equal(hypotheses[1].suspectDisplayName, "Gamma");
  // Cards 2,3 → s0 → "Alpha"
  assert.equal(hypotheses[2].suspectDisplayName, "Alpha");
  assert.equal(hypotheses[3].suspectDisplayName, "Alpha");
  // Cards 4,5 → s1 → "Beta"
  assert.equal(hypotheses[4].suspectDisplayName, "Beta");
  assert.equal(hypotheses[5].suspectDisplayName, "Beta");
});

test("frozen input array is not mutated by buildHypotheses", () => {
  const order = Object.freeze(["s0", "s1", "s2"] as SuspectId[]) as readonly SuspectId[];
  // If the builder tried to sort/reverse/push the array this would throw in strict mode.
  assert.doesNotThrow(() => buildHypotheses(SAMPLE_SUSPECTS, order));
});

test("frozen Suspect objects are not mutated by buildHypotheses", () => {
  const frozen: readonly Suspect[] = Object.freeze(
    SAMPLE_SUSPECTS.map((s) => Object.freeze({ ...s, face: Object.freeze({ ...s.face }) })),
  ) as readonly Suspect[];
  assert.doesNotThrow(() => buildHypotheses(frozen, ["s0", "s1", "s2"]));
  // Confirm the original objects are unchanged (deep equality).
  for (let i = 0; i < SAMPLE_SUSPECTS.length; i++) {
    assert.deepEqual(frozen[i], SAMPLE_SUSPECTS[i]);
  }
});

test("returned array is independent of input — mutating result does not affect subsequent calls", () => {
  const order: SuspectId[] = ["s0", "s1", "s2"];
  const first = buildHypotheses(SAMPLE_SUSPECTS, order);
  // Mutate the returned array.
  first.splice(0, 6);
  assert.equal(first.length, 0);
  // A fresh call should still return six items.
  const second = buildHypotheses(SAMPLE_SUSPECTS, order);
  assert.equal(second.length, 6);
});

test("hypothesis.ts source does not import solver, validatePuzzle, or private answer modules", () => {
  const source = readFileSync(
    join(import.meta.dirname ?? process.cwd(), "../src/lib/game/hypothesis.ts"),
    "utf8",
  );
  // Confirm the file does not import the solver, generator, render, or server modules.
  const forbidden = ["solver", "validatePuzzle", "generator", "render", "server-only", "share-store"];
  for (const term of forbidden) {
    assert.ok(
      !source.includes(`"${term}"`) && !source.includes(`'${term}'`),
      `hypothesis.ts must not import "${term}"`,
    );
  }
});

/** The engine has no DOM, network, AI, storage, or framework dependencies. */
import type { Locale } from "../i18n/locales";
export type { Locale } from "../i18n/locales";
export const SUSPECT_IDS = ["s0", "s1", "s2"] as const;
export type SuspectId = (typeof SUSPECT_IDS)[number];
export const OBJECT_KINDS = ["cup", "lamp", "electronics", "book", "plant", "toy", "other"] as const;
export type ObjectKind = (typeof OBJECT_KINDS)[number];
export const PERSONALITY_IDS = ["dry", "dramatic", "sleepy", "cheerful"] as const;
export type PersonalityId = (typeof PERSONALITY_IDS)[number];
export type StoryId = "coffee" | "sticker";

export type Claim =
  | { type: "culprit_is"; suspectId: SuspectId }
  | { type: "fact_is"; value: boolean }
  | { type: "fact_or_culprit"; value: boolean; suspectId: SuspectId; negated: boolean };
export type World = { culpritId: SuspectId; fact: boolean };
export type Statement = { id: string; speakerId: SuspectId; claim: Claim };
export type Suspect = {
  id: SuspectId;
  displayName: string;
  /** Localizable sample identity only; remove this marker when the player renames it. */
  sampleName?: "cup" | "lamp" | "keyboard";
  kind: string;
  face: { x: number; y: number; scale: number; rotation: number };
  personalityId: string;
};
export type Triple<T> = [T, T, T];
export type RoleAssignment = { a: SuspectId; b: SuspectId; c: SuspectId };
export type CaseDraft = {
  schemaVersion: 1;
  templateId: "opposed-facts" | "conditional-alibis";
  templateVersion: 1 | 2;
  storyId: StoryId;
  storyVersion: 1;
  factId: "lamp-on-at-spill" | "bell-after-midnight";
  factSubjectId?: SuspectId;
  roleAssignment: RoleAssignment;
  factInverted: boolean;
  displayOrder: Triple<SuspectId>;
  locale: Locale;
  suspects: Triple<Suspect>;
  statements: Triple<Statement>;
};
export type PublicStatement = { id: string; speakerId: SuspectId; text: string };
export type PublicSnapshot = {
  locale: Locale;
  title: string;
  context: string;
  suspects: Suspect[];
  statements: PublicStatement[];
  characterLines: Record<SuspectId, string[]>;
  /** Optional only for immutable shares created before the interrogation expansion. */
  interrogations?: import('./interrogation').Interrogations;
  /** Public event alternatives, ordered false then true; neither is marked correct. */
  factLabels?: [string, string];
};
export type CaseResolution = {
  correct: boolean;
  accusedId: SuspectId;
  culpritId: SuspectId;
  proofSteps: string[];
  confession: string;
  fact: boolean;
};
